#include "holdem/preflop.hpp"

#include <stdexcept>

namespace holdem {

namespace {
// Generated by tools/precompute.cpp — defines kTableTrials[9] and
// kPreflopTable[9][169]. Regenerate with:  ./build/precompute src/preflop_table.inc
#include "preflop_table.inc"
}  // namespace

const PreflopOdds& preflop_odds(int index, int opponents) {
  if (index < 0 || index >= kNumStartingHands) throw std::out_of_range("starting hand index");
  if (opponents < 1 || opponents > kMaxTableOpponents) throw std::out_of_range("opponents (1..9)");
  return kPreflopTable[opponents - 1][index];
}

const PreflopOdds& preflop_odds(Hand hole, int opponents) {
  const int index = starting_hand_index(hole);
  if (index < 0) throw std::invalid_argument("hole must be exactly 2 cards");
  return preflop_odds(index, opponents);
}

std::uint64_t preflop_table_trials(int opponents) {
  if (opponents < 1 || opponents > kMaxTableOpponents) return 0;
  return kTableTrials[opponents - 1];
}

}  // namespace holdem
